// ---- ベンダーアップデート履歴ページ -----------------------------------------
// posts.json から自動抽出した独自の時系列データベース。
// 業界全体の動きを「ベンダー軸」で再編集することで、他では一覧化されていない価値を提供。

const VENDOR_TRACKERS = [
  { id: 'autodesk', name: 'Autodesk', keywords: ['autodesk', 'revit', 'forma', 'construction cloud', 'fusion', 'navisworks', 'civil 3d', 'autocad'] },
  { id: 'graphisoft', name: 'Graphisoft', keywords: ['graphisoft', 'archicad', 'bimcloud', 'bimx'] },
  { id: 'nemetschek', name: 'Nemetschek Group', keywords: ['nemetschek', 'allplan', 'vectorworks', 'bluebeam', 'maxon', 'redshift'] },
  { id: 'trimble', name: 'Trimble', keywords: ['trimble', 'tekla', 'sketchup'] },
  { id: 'bentley', name: 'Bentley', keywords: ['bentley', 'openbuildings', 'projectwise', 'synchro', 'staad'] },
  { id: 'fukui-computer', name: '福井コンピュータ', keywords: ['福井コンピュータ', 'gloobe', 'glooobe', 'j-bim'] },
  { id: 'hexagon', name: 'Hexagon', keywords: ['hexagon', 'leica', 'multivista'] },
  { id: 'buildingsmart', name: 'buildingSMART', keywords: ['buildingsmart', 'building smart', 'openbim'] },
  { id: 'procore', name: 'Procore', keywords: ['procore'] },
  { id: 'speckle', name: 'Speckle', keywords: ['speckle'] },
];

function matchesVendor(post, vendor) {
  const haystack = `${post.title || ''} ${post.titleJa || ''} ${post.summary || ''} ${post.bodyJa || ''}`.toLowerCase();
  return vendor.keywords.some((kw) => haystack.includes(kw.toLowerCase()));
}

function buildTimelinePage(posts) {
  const pageTitle = `BIM/AECベンダー アップデート履歴データベース | ${SITE_NAME}`;
  const pageDesc = 'Autodesk、Graphisoft、Nemetschek、Trimble、Bentley、福井コンピュータなど主要BIM/AECベンダーの製品アップデート・買収・戦略発表を時系列で整理した独自データベースです。';
  const canonicalUrl = `${SITE_URL}/timeline.html`;
  const pageJsonLd = webPageJsonLd(pageTitle, pageDesc, canonicalUrl);
  const breadcrumbLd = breadcrumbJsonLd([
    { name: 'ホーム', url: `${SITE_URL}/` },
    { name: 'ベンダーアップデート履歴', url: canonicalUrl },
  ]);

  const vendorBlocks = VENDOR_TRACKERS.map((vendor) => {
    const matching = posts
      .filter((p) => (p.titleJa || '').trim().length > 0)
      .filter((p) => matchesVendor(p, vendor))
      .sort((a, b) => {
        const da = a.pubDate ? new Date(a.pubDate).getTime() : 0;
        const db = b.pubDate ? new Date(b.pubDate).getTime() : 0;
        return db - da;
      });
    if (matching.length === 0) return null;

    const items = matching.slice(0, 20).map((p) => {
      const date = p.pubDate ? formatDate(p.pubDate) : '';
      return `
        <li class="vendor-timeline-item">
          <span class="vendor-timeline-date">${escape(date || '日付不明')}</span>
          <div class="vendor-timeline-content">
            <a class="vendor-timeline-title" href="./posts/${escape(p.slug)}.html">${escape(p.titleJa || p.title)}</a>
            <span class="vendor-timeline-cat">${escape(categoryLabel(p.category))}</span>
          </div>
        </li>`;
    }).join('');

    return `
      <section class="vendor-block" id="vendor-${vendor.id}">
        <h2 class="vendor-block-title">${escape(vendor.name)} <span class="vendor-count">${matching.length}件</span></h2>
        <ol class="vendor-timeline">${items}</ol>
      </section>`;
  }).filter(Boolean).join('');

  const vendorNav = VENDOR_TRACKERS.map((v) => {
    const count = posts.filter((p) => (p.titleJa || '').trim().length > 0 && matchesVendor(p, v)).length;
    if (count === 0) return '';
    return `<li><a href="#vendor-${v.id}">${escape(v.name)}<span class="vendor-nav-count">${count}</span></a></li>`;
  }).filter(Boolean).join('');

  return htmlHead(pageTitle, pageDesc, canonicalUrl, '.', [pageJsonLd, breadcrumbLd], {
    robots: 'index, follow, max-snippet:-1, max-image-preview:large',
    keywords: ['BIMベンダー', 'Autodesk アップデート', 'Graphisoft アップデート', 'AEC業界 動向'],
  }) +
    htmlHeader() +
    `
  <div class="container">
    <main class="main-content">
      <div class="static-page">
        <h1>BIM/AECベンダー アップデート履歴データベース</h1>

        <p>本ページは、AEC News Japan が収集・編集したニュース記事から、主要BIM/AECベンダーごとの動きを自動抽出して時系列に再整理した独自データベースです。「Autodeskは過去半年で何を発表したか」「Graphisoftの最近のリリースを一覧したい」といった、ベンダー軸での情報追跡を可能にします。</p>

        <p style="background: var(--blue-pale); padding: 1rem 1.25rem; border-radius:8px; border-left:4px solid var(--blue); font-size:0.9rem; line-height:1.7;"><strong>本データベースの位置づけ:</strong> 編集部が収集した記事から「ベンダー名・製品名のキーワードマッチ」で自動抽出しています。各ベンダーの戦略変化、買収、製品ローンチ、組織改編などをまとめて把握するための一次インデックスとしてご活用ください。各記事の詳細は元記事へのリンクからご確認いただけます。</p>

        <nav class="vendor-nav">
          <h2 class="vendor-nav-title">ベンダー一覧</h2>
          <ul>${vendorNav}</ul>
        </nav>

        ${vendorBlocks}

        <h2>関連リソース</h2>
        <ul>
          <li><a href="./compare.html">主要BIMツール比較マトリクス</a> — ツール選定の判断軸</li>
          <li><a href="./guides/index.html">BIM基礎解説</a> — 用語と概念の整理</li>
          <li><a href="./categories/bim-ecosystem.html">BIM全般のニュース</a> — 業界横断の動き</li>
        </ul>

        <p style="margin-top:2rem; color: var(--text-muted); font-size:0.85rem;">最終更新日: ${formatDate(new Date().toISOString())}</p>
        <p style="color: var(--text-muted); font-size:0.85rem;">本データベースは編集部が収集した公開記事から自動抽出しています。各ベンダーの公式アップデート履歴ではありません。最新情報は各ベンダー公式サイトをご確認ください。</p>
      </div>
    </main>
  </div>` +
    htmlFooter();
}

function buildCompareTablePage(posts) {
  const pageTitle = `主要BIMツール徹底比較マトリクス | ${SITE_NAME}`;
  const pageDesc = 'Revit、Archicad、GLOOBE、Vectorworks、Allplan、Tekla、OpenBuildings、BricsCAD BIM の主要BIM/AECツール8製品を、価格・IFC対応・日本拡張機能・ST-Bridge対応・構造連携・MEP・施工管理・AI機能・クラウド共同編集・国土交通省BIM/CIM対応など13項目で比較した独自マトリクスです。';
  const canonicalUrl = `${SITE_URL}/compare.html`;
  const pageJsonLd = webPageJsonLd(pageTitle, pageDesc, canonicalUrl);
  const breadcrumbLd = breadcrumbJsonLd([
    { name: 'ホーム', url: `${SITE_URL}/` },
    { name: '主要BIMツール比較マトリクス', url: canonicalUrl },
  ]);

  const tools = BIM_TOOL_COMPARISON.tools;
  const criteria = BIM_TOOL_COMPARISON.criteria;

  const headerRow = `<tr><th class="cmp-criterion">比較項目</th>${tools.map((t) => `<th class="cmp-tool"><span class="cmp-tool-name">${escape(t.name)}</span><span class="cmp-tool-vendor">${escape(t.vendor)}</span></th>`).join('')}</tr>`;
  const bodyRows = criteria.map((c) => {
    const cells = tools.map((t) => `<td>${escape(c.values[t.id] || '—')}</td>`).join('');
    const note = c.note ? `<div class="cmp-note">${escape(c.note)}</div>` : '';
    return `<tr><th class="cmp-row-label">${escape(c.label)}${note}</th>${cells}</tr>`;
  }).join('');

  return htmlHead(pageTitle, pageDesc, canonicalUrl, '.', [pageJsonLd, breadcrumbLd], {
    robots: 'index, follow, max-snippet:-1, max-image-preview:large',
    keywords: ['BIM 比較', 'Revit Archicad 比較', 'BIMツール 選定', 'GLOOBE Revit', 'ST-Bridge'],
  }) +
    htmlHeader() +
    `
  <div class="container">
    <main class="main-content">
      <div class="static-page">
        <h1>主要BIMツール徹底比較マトリクス（2026年版）</h1>

        <p>日本の建築・建設実務でBIM導入を検討する際、海外発信の比較記事は仕様や価格を網羅しているものの、日本特有の評価軸（日本拡張機能、ST-Bridge対応、国土交通省BIM/CIM標準への準拠、日本国内サポート体制など）が抜け落ちていることが多くあります。本マトリクスは、海外発信のグローバル仕様情報と、日本市場に特化した評価項目を統合し、編集部が独自に整理した8製品×13項目の比較表です。</p>

        <p style="background: var(--blue-pale); padding: 1rem 1.25rem; border-radius:8px; border-left:4px solid var(--blue); font-size:0.9rem; line-height:1.7;"><strong>本マトリクスの位置づけ:</strong> ツール選定の出発点となる「ファーストパス」のフィルタリング資料です。最終的な選定は、貴社の業務フロー、既存資産（CADデータ、テンプレート、ファミリ）、社内スキルセット、案件パイプラインに合わせて、各販社の実機デモ・トライアル契約を経て判断してください。価格・仕様は2026年時点の参考情報であり、変更されている可能性があります。</p>

        <h2>比較マトリクス本体</h2>
        <div class="cmp-table-wrapper">
          <table class="cmp-table">
            <thead>${headerRow}</thead>
            <tbody>${bodyRows}</tbody>
          </table>
        </div>

        <h2>編集部視点：選び方の判断軸</h2>
        <h3>意匠設計事務所が初めてBIM導入する場合</h3>
        <p>意匠表現の自由度、ファミリ・ライブラリの充実度、学習曲線の緩やかさを重視するなら <strong>Archicad</strong> または <strong>GLOOBE</strong> が候補。Archicadは国際的なBIMコミュニティとの親和性、GLOOBEは日本の建築実務（確認申請、構造一体運用）への適合度で優位。</p>

        <h3>ゼネコン設計部門が大規模化を見据える場合</h3>
        <p><strong>Revit</strong> が事実上の業界標準。Autodesk Construction Cloud / Forma との連携でBIM360時代から続く施工管理連携、海外案件・外注先との互換性が決め手。日本での人材プールも最大。</p>

        <h3>構造設計・鉄骨ファブが中心の場合</h3>
        <p><strong>Tekla Structures</strong> 一択に近い。構造ディテール表現力、製作図出力、鉄骨製造プロセスとの連携で他ツールを圧倒。</p>

        <h3>インフラ・公共大型案件中心の場合</h3>
        <p>Bentley の <strong>OpenBuildings Designer</strong> または Tekla / Revit の組み合わせ。国土交通省BIM/CIM案件の入札条件にも依存。</p>

        <h3>DWG資産との互換を最重視する場合</h3>
        <p><strong>BricsCAD BIM</strong> が現実解。AutoCAD互換ながらBIMモデリング機能を持ち、コスト面でも他のBIMツールより抑えやすい。</p>

        <h2>導入時に見落としがちな観点</h2>
        <ul>
          <li><strong>クラウド共同編集の運用コスト</strong>：複数人で同時編集する場合、サブスクの追加ライセンス費用が必要なケースが多い</li>
          <li><strong>テンプレート・ファミリ整備の社内工数</strong>：ツール選定後、社内テンプレ整備に半年〜1年かかる前提を持つ</li>
          <li><strong>下請け・協力会社の互換性</strong>：自社で導入してもデータの受け渡し相手が異なるツールを使う場合、IFC経由でのやり取りに精度ロスが生じる</li>
          <li><strong>サポート言語</strong>：海外ツールは日本語サポートの厚みに差がある。販社経由の保守体制を必ず事前確認</li>
          <li><strong>建築確認申請対応</strong>：BIM確認申請対応の動きが進む中、各ツールの図面出力品質と確認機関の運用相性を確認</li>
        </ul>

        <h2>ツール別の最新ニュース</h2>
        <p>各ツールの最新動向・アップデート情報は、以下のカテゴリ別ニュース一覧から確認できます。</p>
        <ul>
          <li><a href="./categories/revit.html">Revit関連ニュース</a></li>
          <li><a href="./categories/archicad.html">Archicad関連ニュース</a></li>
          <li><a href="./categories/gloobe.html">GLOOBE関連ニュース</a></li>
          <li><a href="./categories/bim-ecosystem.html">BIM全般のニュース</a></li>
        </ul>

        <h2>合わせて読みたい基礎解説</h2>
        <ul>
          <li><a href="./guides/bim.html">BIMとは何か（基礎解説）</a></li>
          <li><a href="./guides/revit.html">Revit徹底解説</a></li>
          <li><a href="./guides/archicad.html">Archicad徹底解説</a></li>
          <li><a href="./guides/ifc.html">IFCとは何か</a></li>
          <li><a href="./guides/openbim.html">openBIMの考え方</a></li>
          <li><a href="./guides/bim-manager.html">BIMマネージャーの役割</a></li>
        </ul>

        <p style="margin-top:2rem; color: var(--text-muted); font-size:0.85rem;">最終更新日: ${formatDate(new Date().toISOString())}</p>
        <p style="color: var(--text-muted); font-size:0.85rem;">本マトリクスは編集部の独自整理によるものであり、各ベンダーの公式比較資料ではありません。詳細な仕様確認は各社公式情報をご参照ください。</p>
      </div>
    </main>
  </div>` +
    htmlFooter();
}

function buildEventsPage(events) {
  const now = Date.now();
  const upcoming = events.filter((ev) => {
    if (!ev.date) return true;
    const d = new Date(ev.date).getTime();
    return isNaN(d) || d >= now;
  });
  const past = events.filter((ev) => {
    if (!ev.date) return false;
    const d = new Date(ev.date).getTime();
    return !isNaN(d) && d < now;
  });

  function formatEventDate(ev) {
    if (!ev.date) return '日程未定';
    const d = new Date(ev.date);
    if (isNaN(d.getTime())) return '日程未定';
    const dateStr = d.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric' });
    if (ev.dateEnd) {
      const de = new Date(ev.dateEnd);
      if (!isNaN(de.getTime())) {
        return `${dateStr} - ${de.toLocaleDateString('ja-JP', { month: 'long', day: 'numeric' })}`;
      }
    }
    return dateStr;
  }

  function eventCard(ev) {
    const dateLabel = formatEventDate(ev);
    const location = escape(ev.location || '');
    const source = escape(ev.source || '');
    const desc = ev.description ? `<p class="event-desc">${escape(ev.description)}</p>` : '';
    return `
        <article class="event-card">
          <div class="event-meta">
            <span class="event-date">開催日: ${escape(dateLabel)}</span>
            ${location ? `<span class="event-location">会場: ${location}</span>` : ''}
            ${source ? `<span class="event-source">主催: ${source}</span>` : ''}
          </div>
          <h2 class="event-title">
            <a href="${escape(ev.url)}" target="_blank" rel="noopener noreferrer">${escape(ev.title)}</a>
          </h2>
          ${desc}
          <a class="event-link" href="${escape(ev.url)}" target="_blank" rel="noopener noreferrer">詳細・登録を見る</a>
        </article>`;
  }

  const upcomingHtml = upcoming.length > 0
    ? upcoming.map(eventCard).join('')
    : '<p class="event-empty">現在、掲載中の開催予定イベントはありません。</p>';

  const pastHtml = past.length > 0 ? past.map(eventCard).join('') : '';
  const pastSection = past.length > 0
    ? `<h2 class="events-section-title">開催済み</h2><div class="event-list past">${pastHtml}</div>`
    : '';

  const eventStyles = `
    .events-hero { background: var(--navy); color: var(--white); padding: 2.5rem 1.5rem; text-align: center; }
    .events-hero h1 { font-size: 1.75rem; font-weight: 700; }
    .events-hero p { opacity: 0.75; margin-top: 0.5rem; font-size: 0.95rem; }
    .events-main { max-width: 820px; margin: 2.5rem auto; padding: 0 1.5rem 4rem; }
    .events-section-title { font-size: 1.2rem; font-weight: 700; color: var(--navy); margin: 2.5rem 0 1rem; border-left: 4px solid var(--blue); padding-left: 0.75rem; }
    .event-list { display: flex; flex-direction: column; gap: 1.25rem; }
    .event-card { background: var(--white); border-radius: 10px; padding: 1.4rem 1.6rem; box-shadow: var(--card-shadow); border: 1px solid var(--border); }
    .event-list.past .event-card { opacity: 0.6; }
    .event-meta { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; font-size: 0.82rem; color: var(--text-muted); margin-bottom: 0.6rem; }
    .event-date { font-weight: 600; color: var(--blue); }
    .event-title { font-size: 1.05rem; font-weight: 700; line-height: 1.5; margin-bottom: 0.5rem; }
    .event-title a { color: var(--text); }
    .event-title a:hover { color: var(--blue); text-decoration: none; }
    .event-desc { font-size: 0.88rem; color: var(--text-muted); line-height: 1.65; margin-bottom: 0.75rem; }
    .event-link { font-size: 0.85rem; font-weight: 600; color: var(--blue); }
    .event-empty { color: var(--text-muted); font-size: 0.95rem; padding: 2rem 0; }`;

  const pageTitle = `イベント情報 | ${SITE_NAME}`;
  const pageDesc = 'BIM・AEC・建設DX関連の日本開催イベント・セミナー情報をまとめています。';
  const canonicalUrl = `${SITE_URL}/events.html`;
  const eventsJsonLd = collectionPageJsonLd(pageTitle, pageDesc, canonicalUrl);
  const breadcrumbLd = breadcrumbJsonLd([
    { name: 'ホーム', url: `${SITE_URL}/` },
    { name: 'イベント情報', url: canonicalUrl },
  ]);

  return htmlHead(pageTitle, pageDesc, canonicalUrl, '.', [eventsJsonLd, breadcrumbLd]).replace('</style>', eventStyles + '\n  </style>') +
    htmlHeader('.') +
    `
  <div class="events-hero">
    <h1>イベント情報</h1>
    <p>BIM・AEC・建設DX関連の日本開催イベント・セミナー</p>
  </div>
  <div class="events-main">
    <h2 class="events-section-title">開催予定</h2>
    <div class="event-list">${upcomingHtml}</div>
    ${pastSection}
  </div>` +
    htmlFooter('.');
}

// ---- main -------------------------------------------------------------------

function main() {
  const postsFile = path.join(__dirname, 'data', 'posts.json');

  if (!fs.existsSync(postsFile)) {
    console.error('[generateSite] data/posts.json not found — skipping site generation');
    process.exit(0);
  }

  let posts;
  try {
    posts = JSON.parse(fs.readFileSync(postsFile, 'utf-8'));
  } catch (err) {
    console.error('[generateSite] Failed to parse posts.json:', err.message);
    process.exit(1);
  }

  if (!Array.isArray(posts) || posts.length === 0) {
    console.warn('[generateSite] No posts found — generating empty site');
    posts = [];
  }

  posts = [...MANUAL_POSTS, ...posts];

  // titleJaが空の記事（日本語化できなかった＝BIM無関係と判定済み）をサイト表示から除外
  const before = posts.length;
  posts = posts.filter((p) => p.titleJa && p.titleJa.trim() !== '');
  const excluded = before - posts.length;
  if (excluded > 0) {
    console.log(`[generateSite] titleJa未設定の記事を除外: ${excluded}件`);
  }

  // Assign slugs — respect pre-set slugs (e.g. weekly-YYYY-MM-DD)
  const usedSlugs = new Map();
  posts = posts.map((post) => {
    // If the post already has a valid slug, keep it
    if (post.slug && /^[a-z0-9-]+$/.test(post.slug)) {
      usedSlugs.set(post.slug, true);
      return post;
    }
    let base = slugify(post.title || 'post');
    if (!base) base = 'post';
    let slug = base;
    let counter = 1;
    while (usedSlugs.has(slug)) {
      slug = `${base}-${counter}`;
      counter++;
    }
    usedSlugs.set(slug, true);
    return { ...post, slug };
  });

  // Sort posts by pubDate descending (newest first)
  posts.sort((a, b) => {
    const da = a.pubDate ? new Date(a.pubDate).getTime() : 0;
    const db = b.pubDate ? new Date(b.pubDate).getTime() : 0;
    return db - da;
  });

  const archivePosts = posts.slice(HOME_FEATURED_POSTS);
  const homeArchivePageCount = Math.max(1, Math.ceil(archivePosts.length / HOME_ARTICLES_PER_PAGE));

  // Ensure posts/ directory exists
  const postsDir = path.join(__dirname, 'posts');
  if (!fs.existsSync(postsDir)) {
    fs.mkdirSync(postsDir, { recursive: true });
  }
  const expectedPostFiles = new Set(posts.map((post) => `${post.slug}.html`));
  const existingPostFiles = fs.readdirSync(postsDir).filter((name) => name.endsWith('.html'));
  let removedPostCount = 0;
  for (const filename of existingPostFiles) {
    if (!expectedPostFiles.has(filename)) {
      fs.unlinkSync(path.join(postsDir, filename));
      removedPostCount++;
    }
  }
  if (removedPostCount > 0) {
    console.log(`[generateSite] Removed ${removedPostCount} stale article pages from posts/`);
  }

  // Generate index.html
  fs.writeFileSync(path.join(__dirname, 'index.html'), buildIndex(posts, posts.length), 'utf-8');
  const pageDir = path.join(__dirname, 'page');
  if (!fs.existsSync(pageDir)) {
    fs.mkdirSync(pageDir, { recursive: true });
  }
  const expectedArchiveDirs = new Set(
    Array.from({ length: Math.max(0, homeArchivePageCount - 1) }, (_, index) => String(index + 2))
  );
  const existingArchiveDirs = fs.readdirSync(pageDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && /^\d+$/.test(entry.name))
    .map((entry) => entry.name);
  for (const dirName of existingArchiveDirs) {
    if (!expectedArchiveDirs.has(dirName)) {
      fs.rmSync(path.join(pageDir, dirName), { recursive: true, force: true });
    }
  }
  for (let pageNumber = 2; pageNumber <= homeArchivePageCount; pageNumber++) {
    const pagePosts = archivePosts.slice(
      (pageNumber - 2) * HOME_ARTICLES_PER_PAGE + HOME_ARTICLES_PER_PAGE,
      (pageNumber - 1) * HOME_ARTICLES_PER_PAGE + HOME_ARTICLES_PER_PAGE
    );
    const targetDir = path.join(pageDir, String(pageNumber));
    fs.mkdirSync(targetDir, { recursive: true });
    fs.writeFileSync(
      path.join(targetDir, 'index.html'),
      buildHomeArchivePage(pagePosts, posts, pageNumber, homeArchivePageCount),
      'utf-8'
    );
  }
  console.log(`[generateSite] Generated index.html${homeArchivePageCount > 1 ? ` + ${homeArchivePageCount - 1} archive pages` : ''}`);

  // Generate individual article pages
  let articleCount = 0;
  for (const post of posts) {
    const html = buildArticlePage(post, posts);
    fs.writeFileSync(path.join(postsDir, `${post.slug}.html`), html, 'utf-8');
    articleCount++;
  }
  console.log(`[generateSite] Generated ${articleCount} article pages in posts/`);

  // Generate explainer guide pages
  const guidesDir = path.join(__dirname, 'guides');
  if (!fs.existsSync(guidesDir)) {
    fs.mkdirSync(guidesDir, { recursive: true });
  }
  const expectedGuideFiles = new Set(['index.html', ...EXPLAINER_GUIDES.map((guide) => `${guide.slug}.html`)]);
  const existingGuideFiles = fs.readdirSync(guidesDir).filter((name) => name.endsWith('.html'));
  let removedGuideCount = 0;
  for (const filename of existingGuideFiles) {
    if (!expectedGuideFiles.has(filename)) {
      fs.unlinkSync(path.join(guidesDir, filename));
      removedGuideCount++;
    }
  }
  if (removedGuideCount > 0) {
    console.log(`[generateSite] Removed ${removedGuideCount} stale guide pages from guides/`);
  }
  let guideCount = 0;
  for (const guide of EXPLAINER_GUIDES) {
    const html = buildExplainerPage(guide, posts);
    fs.writeFileSync(path.join(guidesDir, `${guide.slug}.html`), html, 'utf-8');
    guideCount++;
  }
  fs.writeFileSync(path.join(guidesDir, 'index.html'), buildGuidesIndexPage(posts), 'utf-8');
  console.log(`[generateSite] Generated ${guideCount} explainer pages in guides/`);

  // Generate category pages
  const categoriesDir = path.join(__dirname, 'categories');
  if (!fs.existsSync(categoriesDir)) {
    fs.mkdirSync(categoriesDir, { recursive: true });
  }
  const allCategories = [...new Set(posts.map((p) => (p.category || 'OTHER').toUpperCase()))];
  const expectedCategoryFiles = new Set(allCategories.map((cat) => `${categorySlug(cat)}.html`));
  const existingCategoryFiles = fs.readdirSync(categoriesDir).filter((name) => name.endsWith('.html'));
  let removedCategoryCount = 0;
  for (const filename of existingCategoryFiles) {
    if (!expectedCategoryFiles.has(filename)) {
      fs.unlinkSync(path.join(categoriesDir, filename));
      removedCategoryCount++;
    }
  }
  if (removedCategoryCount > 0) {
    console.log(`[generateSite] Removed ${removedCategoryCount} stale category pages from categories/`);
  }
  let categoryCount = 0;
  for (const cat of allCategories) {
    const slug = categorySlug(cat);
    const html = buildCategoryPage(cat, posts);
    fs.writeFileSync(path.join(categoriesDir, `${slug}.html`), html, 'utf-8');
    categoryCount++;
  }
  console.log(`[generateSite] Generated ${categoryCount} category pages in categories/`);

  // Generate static pages
  fs.writeFileSync(path.join(__dirname, 'privacy.html'), buildPrivacyPage(), 'utf-8');
  console.log('[generateSite] Generated privacy.html');

  fs.writeFileSync(path.join(__dirname, 'about.html'), buildAboutPage(), 'utf-8');
  console.log('[generateSite] Generated about.html');

  fs.writeFileSync(path.join(__dirname, 'compare.html'), buildCompareTablePage(posts), 'utf-8');
  console.log('[generateSite] Generated compare.html');

  fs.writeFileSync(path.join(__dirname, 'timeline.html'), buildTimelinePage(posts), 'utf-8');
  console.log('[generateSite] Generated timeline.html');

  fs.writeFileSync(path.join(__dirname, 'glossary.html'), buildGlossaryPage(), 'utf-8');
  console.log('[generateSite] Generated glossary.html');

  // Generate events.html
  const eventsFile = path.join(__dirname, 'data', 'events.json');
  let events = [];
  if (fs.existsSync(eventsFile)) {
    try { events = JSON.parse(fs.readFileSync(eventsFile, 'utf-8')); } catch { events = []; }
  }
  fs.writeFileSync(path.join(__dirname, 'events.html'), buildEventsPage(events), 'utf-8');
  console.log(`[generateSite] Generated events.html (${events.length}件)`);

  // Generate sitemap.xml
  const now = new Date().toISOString().split('T')[0];
  const paginatedHomeUrls = Array.from({ length: Math.max(0, homeArchivePageCount - 1) }, (_, index) => ({
    loc: homeArchiveUrl(index + 2),
    lastmod: now,
    changefreq: 'weekly',
    priority: '0.6',
  }));
  const categoryUrls = allCategories.map((cat) => ({
    loc: `${SITE_URL}/categories/${categorySlug(cat)}.html`,
    lastmod: now,
    changefreq: 'weekly',
    priority: '0.7',
  }));
  const staticUrls = [
    { loc: `${SITE_URL}/`, lastmod: now, changefreq: 'daily', priority: '1.0' },
    { loc: `${SITE_URL}/guides/index.html`, lastmod: now, changefreq: 'weekly', priority: '0.9' },
    { loc: `${SITE_URL}/events.html`, lastmod: now, changefreq: 'weekly', priority: '0.8' },
    { loc: `${SITE_URL}/compare.html`, lastmod: now, changefreq: 'monthly', priority: '0.9' },
    { loc: `${SITE_URL}/timeline.html`, lastmod: now, changefreq: 'weekly', priority: '0.8' },
    { loc: `${SITE_URL}/glossary.html`, lastmod: now, changefreq: 'monthly', priority: '0.9' },
    ...paginatedHomeUrls,
    ...categoryUrls,
  ];
  const articleUrls = posts.map((post) => {
    const lastmod = post.pubDate
      ? new Date(post.pubDate).toISOString().split('T')[0]
      : now;
    return { loc: `${SITE_URL}/posts/${post.slug}.html`, lastmod, changefreq: 'monthly', priority: '0.8' };
  });
  const guideUrls = EXPLAINER_GUIDES.map((guide) => ({
    loc: `${SITE_URL}/guides/${guide.slug}.html`,
    lastmod: now,
    changefreq: 'monthly',
    priority: '0.7',
  }));
  const allUrls = [...staticUrls, ...guideUrls, ...articleUrls];
  const sitemapXml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${allUrls.map((u) => `  <url>
    <loc>${u.loc}</loc>
    <lastmod>${u.lastmod}</lastmod>
    <changefreq>${u.changefreq}</changefreq>
    <priority>${u.priority}</priority>
  </url>`).join('\n')}
</urlset>`;
  fs.writeFileSync(path.join(__dirname, 'sitemap.xml'), sitemapXml, 'utf-8');
  console.log(`[generateSite] Generated sitemap.xml (${allUrls.length} URLs)`);

  // Generate robots.txt
  const robotsTxt = `User-agent: *
Allow: /
Disallow: /assets/
Crawl-delay: 10

Sitemap: ${SITE_URL}/sitemap.xml
`;
  fs.writeFileSync(path.join(__dirname, 'robots.txt'), robotsTxt, 'utf-8');
  console.log('[generateSite] Generated robots.txt');

  console.log('[generateSite] Done.');
}

main();
